use super::*;

/// Which base (`commons` or `integration`) `id` names — `is_lane_stream(id)` must already be true.
pub(crate) fn lane_base(id: &str) -> &'static str {
    if id == COMMONS_STREAM_ID || id.starts_with("commons--") {
        COMMONS_STREAM_ID
    } else {
        INTEGRATION_STREAM_ID
    }
}
